['protocol', 'userInfo', 'host', 'port', 'path', 'anchor'].forEach(k => {
  Uri.prototype[k] = function (v) { if (v !== undefined) this._p[k] = String(v); return this._p[k]; };
  Uri.prototype['set' + k[0].toUpperCase() + k.slice(1)] = function (v) { this._p[k] = String(v); return this; };
});
